<?php
require_once __DIR__ . '/config/config.php'; require_once __DIR__ . '/config/helpers.php'; require_login();
$pageTitle='Reports';$from=$_GET['from']??date('Y-m-01');$to=$_GET['to']??date('Y-m-d');
$s=$pdo->prepare('SELECT COUNT(DISTINCT farmer_id) farmers, COUNT(*) bills, COALESCE(SUM(gross_weight_kg),0) weight, COALESCE(SUM(total_amount),0) amount FROM bills WHERE bill_date BETWEEN ? AND ?');$s->execute([$from,$to]);$sum=$s->fetch();
$s=$pdo->prepare("SELECT DATE_FORMAT(bill_date,'%d %b') label, COALESCE(SUM(total_amount),0) amount FROM bills WHERE bill_date BETWEEN ? AND ? GROUP BY bill_date ORDER BY bill_date");$s->execute([$from,$to]);$daily=$s->fetchAll();
$s=$pdo->prepare('SELECT f.name, COUNT(b.id) bills, COALESCE(SUM(b.total_amount),0) amount FROM farmers f JOIN bills b ON b.farmer_id=f.id WHERE b.bill_date BETWEEN ? AND ? GROUP BY f.id ORDER BY amount DESC LIMIT 5');$s->execute([$from,$to]);$top=$s->fetchAll();
include __DIR__.'/includes/header.php';
?><div class="card"><form class="toolbar" method="get"><div class="field"><label>From</label><input type="date" name="from" value="<?=e($from)?>"></div><div class="field"><label>To</label><input type="date" name="to" value="<?=e($to)?>"></div><button class="btn btn-primary">Generate Report</button><button type="button" class="btn btn-light" onclick="printReport()">Export / Print PDF</button></form></div><div class="cards mt"><div class="card"><div class="stat-label">Farmers</div><div class="stat-value"><?=number_format($sum['farmers'])?></div></div><div class="card"><div class="stat-label">Bills</div><div class="stat-value"><?=number_format($sum['bills'])?></div></div><div class="card"><div class="stat-label">Weight</div><div class="stat-value"><?=number_format($sum['weight'],2)?> kg</div></div><div class="card"><div class="stat-label">Amount</div><div class="stat-value"><?=money($sum['amount'])?></div></div></div><div class="report-grid mt"><div class="card chart-card"><div class="section-head" style="margin-top:0"><h2>Daily Purchase Amount</h2></div><canvas id="dailyChart"></canvas></div><div class="card"><div class="section-head" style="margin-top:0"><h2>Top Farmers</h2></div><div style="display:grid;gap:12px"><?php foreach($top as $t):?><div style="display:flex;justify-content:space-between;gap:10px;border-bottom:1px solid #eee;padding-bottom:10px"><div><strong><?=e($t['name'])?></strong><div style="font-size:11px;color:#6b7280"><?=$t['bills']?> bills</div></div><strong><?=money($t['amount'])?></strong></div><?php endforeach;?><?php if(!$top):?><div class="empty">No data.</div><?php endif;?></div></div></div><script src="https://cdn.jsdelivr.net/npm/chart.js@4.4.4/dist/chart.umd.min.js"></script><script>const daily=<?=json_encode($daily)?>;new Chart(document.getElementById('dailyChart'),{type:'bar',data:{labels:daily.map(x=>x.label),datasets:[{label:'Amount (Rs.)',data:daily.map(x=>Number(x.amount))}]},options:{responsive:true,maintainAspectRatio:false,plugins:{legend:{display:false}},scales:{y:{beginAtZero:true}}}});function printReport(){window.print();}</script><?php include __DIR__.'/includes/footer.php'; ?>
